match
$me isa me, has screen_name "neo4j";
$rel isa interacts_with (interactor: $me, target: $user);
reduce $interactions = count($rel) groupby $user;
sort $interactions desc;
limit 5;
fetch { "screen_name": $user.screen_name, "interactions": $interactions };

match
$u isa user, has screen_name "neo4j";
posts (author: $u, content: $t);
reply_to (replying_tweet: $t, original_tweet: $replied);
fetch {
  "tweet_id": $t.id_str,
  "tweet_text": $t.text,
  "created_at": $t.created_at
};

match
$u isa user, has screen_name "neo4j";
mentions (source_tweet: $t, mentioned_user: $u);
$t has created_at $ca;
tags (tagged_tweet: $t, tag: $h);
sort $ca;
limit 3;
fetch { "name": $h.hashtag_name };

match
$t isa tweet, has favorites $f;
$s isa source, has source_name "Buffer";
using (tweet_content: $t, platform: $s);
sort $f desc;
limit 5;
fetch {
  "tweet": $t.text,
  "favorites": $f
};

match
$me isa me, has screen_name "neo4j";
$user isa user, has followers $f;
follows (follower: $me, followed: $user);
$f > 10000;
limit 3;
fetch {
  "screen_name": $user.screen_name,
  "followers": $f
};

match
$u isa user, has name "Neo4j";
posts (author: $u, content: $t);
tags (tagged_tweet: $t, tag: $h);
fetch {
  "tweet_id": $t.tweet_id,
  "text": $t.text,
  "created_at": $t.created_at,
  "favorites": $t.favorites
};

match
$u isa user, has betweenness $b;
sort $b desc;
limit 5;
fetch {
  "screen_name": $u.screen_name,
  "betweenness": $b
};

match
$u isa user, has location "Sweden";
posts (author: $u, content: $t);
using (tweet_content: $t, platform: $s);
$s isa source;
reduce $tweet_count = count($t) groupby $s;
sort $tweet_count desc;
limit 5;
fetch { "source": $s.source_name, "tweet_count": $tweet_count };

match
$t isa tweet, has text $tweet_text, has favorites $fav;
$l isa link, has link_url $lu;
$lu like "https://twitter.com.*";
contains (containing_tweet: $t, contained_link: $l);
sort $fav desc;
limit 3;
fetch {
  "tweet_text": $tweet_text,
  "link_url": $lu,
  "favorites": $fav
};

match
$me isa me, has screen_name "neo4j";
posts (author: $me, content: $retweet);
$retweet isa tweet, has created_at $rt_date;
$rt_date >= 2021-03-16T00:00:00;
$rt_date < 2021-03-17T00:00:00;
retweets (retweeting_tweet: $retweet, original_tweet: $original);
$original isa tweet;
sort $rt_date;
limit 3;
fetch {
  "text": $original.text,
  "created_at": $original.created_at
};

match
$me isa me, has screen_name "neo4j";
follows (follower: $me, followed: $user);
$user has betweenness $b;
sort $b desc;
limit 5;
fetch {
  "name": $user.name,
  "betweenness": $b
};

match
$u isa user, has screen_name "neo4j";
$t isa tweet, has created_at $ca;
mentions (source_tweet: $t, mentioned_user: $u);
tags (tagged_tweet: $t, tag: $h);
$h has hashtag_name $hn;
sort $ca;
limit 3;
fetch {
  "name": $hn
};

match
$u isa user, has profile_image_url $piu, has screen_name $sn, has name $n;
$piu like ".*horned_reaper.*";
$m isa me, has screen_name "neo4j";
follows (follower: $u, followed: $m);
fetch {
  "screen_name": $sn,
  "name": $n,
  "profile_image_url": $piu
};

match
$u isa user, has location "Graphs Are Everywhere";
posts (author: $u, content: $t);
$t has favorites $f;
sort $f desc;
