  "statuses": $s
};

match
$t isa tweet, has text $text, has created_at $created_at;
$u isa user, has name "Neo4j";
mentions (source_tweet: $t, mentioned_user: $u);
$h isa hashtag, has hashtag_name $hn;
tags (tagged_tweet: $t, tag: $h);
sort $created_at desc;
limit 3;
fetch {
  "tweet_text": $text,
  "tweet_date": $created_at,
  "hashtag": $hn
};

match
$u isa user;
$t isa tweet, has created_at $ca;
$m isa me, has screen_name "neo4j";
posts (author: $u, content: $t);
mentions (source_tweet: $t, mentioned_user: $m);
sort $ca asc;
limit 3;
fetch {
  "screen_name": $u.screen_name,
  "created_at": $ca
};

match
$me isa me, has screen_name "neo4j";
follows (follower: $me, followed: $user);
$user has followers $f;
sort $f desc;
limit 5;
fetch {
  "name": $user.name,
  "followers": $f
};

match
$u isa user;
posts (author: $u, content: $t);
reduce $count = count($t) groupby $u;
sort $count desc;
limit 3;
fetch {
  "user": $u.screen_name,
  "tweet_count": $count
};

match
$s isa source, has source_name "Buffer";
$t isa tweet, has created_at $ca;
using (tweet_content: $t, platform: $s);
sort $ca asc;
limit 3;
fetch {
  "created_at": $t.created_at,
  "tweet_id": $t.tweet_id,
  "text": $t.text,
  "favorites": $t.favorites
};

match
$h isa hashtag, has hashtag_name "education";
tags (tagged_tweet: $t, tag: $h);
$t has favorites $f;
sort $f desc;
limit 5;
fetch {
  "tweet_id": $t.tweet_id,
  "text": $t.text,
  "favorites": $t.favorites
};

match
$u isa user, has followers $f;
sort $f desc;
limit 5;
fetch {
  "screen_name": $u.screen_name,
  "followers": $f
};

match
$m isa me, has screen_name "neo4j";
posts (author: $m, content: $original);
retweets (original_tweet: $original, retweeting_tweet: $t);
$u isa user;
posts (author: $u, content: $t);
$u has profile_image_url $piu;
limit 3;
fetch {
  "screen_name": $u.screen_name,
  "profile_image_url": $piu
};

match
$me isa me, has screen_name "neo4j";
posts (author: $me, content: $tweet);
reply_to (replying_tweet: $tweet, original_tweet: $replied);
$replied isa tweet;
fetch {
  "repliedTweet_text": $replied.text,
  "repliedTweet_tweet_id": $replied.tweet_id,
  "repliedTweet_id_str": $replied.id_str,
  "repliedTweet_favorites": $replied.favorites,
  "repliedTweet_created_at": $replied.created_at,
  "repliedTweet_import_method": $replied.import_method
};

match
$me isa me;
$neo4j isa user, has screen_name "neo4j";
$user isa user;
follows (follower: $user, followed: $me);
follows (follower: $user, followed: $neo4j);
$user has followers $fc;
sort $fc desc;
limit 5;
fetch {
  "follower": $user.screen_name,
  "followers_count": $fc
};

match
$me isa me;
$rel isa amplifies (amplifier: $me, amplified_user: $user);
reduce $count = count($rel) groupby $user;
sort $count desc;
limit 3;
fetch {
  "name": $user.name,
  "screen_name": $user.screen_name,
  "amplification_count": $count
};

match
$u isa user, has screen_name "neo4j";
posts (author: $u, content: $t);
$t has favorites $f;
sort $f desc;
limit 5;
fetch {
  "tweet": $t.text,
  "favorites": $f
};

match
$me isa me, has screen_name "neo4j";
$rel isa interacts_with (interactor: $me, target: $user);
reduce $count = count($rel) groupby $user;
sort $count desc;
limit 1;
fetch { "screen_name": $user.screen_name, "interaction_count": $count };

match
$u isa user, has screen_name "neo4j";
posts (author: $u, content: $t);
contains (containing_tweet: $t, contained_link: $l);
fetch {
  "tweet_text": $t.text,
  "link_url": $l.link_url,
  "tweet_date": $t.created_at
};

match
$u isa user, has screen_name "neo4j";
posts (author: $u, content: $t);
retweets (original_tweet: $t, retweeting_tweet: $r);
posts (author: $retweeter, content: $r);
reduce $retweet_count = count($r) groupby $retweeter;
sort $retweet_count desc;
limit 10;
fetch { "retweeter": $retweeter.screen_name, "retweet_count": $retweet_count };

match
$me isa me, has screen_name "neo4j";
follows (follower: $me, followed: $user);
$user has followers $f;
$f > 10000;
fetch {
  "screen_name": $user.screen_name,
  "followers": $f
};

match
$me isa me, has screen_name "neo4j";
$user isa user, has name $follower_name, has followers $follower_count;
follows (follower: $user, followed: $me);
sort $follower_count desc;
limit 5;
fetch {
  "follower_name": $follower_name,
  "follower_count": $follower_count
};

match
$u isa user, has screen_name "neo4j";
posts (author: $u, content: $t);
using (tweet_content: $t, platform: $s);
select $s;
distinct;
fetch {
  "source_name": $s.source_name
};

match
$u isa user, has screen_name "neo4j";
posts (author: $u, content: $t);
