match
$me isa me, has screen_name "neo4j";
posts (author: $me, content: $tweet);
retweets (retweeting_tweet: $tweet, original_tweet: $retweetedTweet);
posts (author: $user, content: $retweetedTweet);
$user isa user;
limit 5;
fetch {
  "retweeted_user": $user.screen_name
};

match
$t isa tweet, has text $text, has favorites $fav;
