};

match
$me isa me, has screen_name "neo4j";
similar_to ($me, $user);
$user has betweenness $ub, has following $uf;
$me has betweenness $mb, has following $mf;
let $similarity_score = abs($ub - $mb) + abs($uf - $mf);
sort $similarity_score asc;
limit 5;
fetch {
  "screen_name": $user.screen_name,
  "user_betweenness": $ub,
  "user_following": $uf,
  "me_betweenness": $mb,
  "me_following": $mf,
  "similarity_score": $similarity_score
};

match
$tweet isa tweet;
$rel isa $t ($tweet);
{ $t label mentions; } or { $t label retweets; } or { $t label reply_to; };
reduce $count = count($rel) groupby $tweet;
sort $count desc;
limit 5;
fetch {
  "tweet_id": $tweet.id_str,
  "tweet_text": $tweet.text,
  "total_interactions": $count
};

match
$u isa user;
$rel isa interacts_with (interactor: $u, target: $other);
reduce $interactions = count($rel) groupby $u;
