match
$s isa stream, has name $sn;
game_play (streaming_channel: $s, played_game: $g);
$g isa game;
select $s, $sn, $g;
distinct;
reduce $count = count($g) groupby $s, $sn;
sort $count desc;
limit 1;
fetch { "streamName": $sn, "uniqueGames": $count };

match
$s isa stream;
$l isa language;
language_usage (channel: $s, used_language: $l);
reduce $languageCount = count($l) groupby $s;
match $languageCount >= 3;
fetch { "streamName": $s.name, "languageCount": $languageCount };

match
$u isa user;
$s isa stream;
chat_activity (chatting_user: $u, channel_with_chatters: $s);
select $u, $s;
distinct;
reduce $streamCount = count($s) groupby $u;
match
$streamCount > 3;
sort $streamCount desc;
limit 5;
fetch {
  "userName": $u.name,
  "streamCount": $streamCount
};

match
$s isa stream;
$g isa game;
game_play (streaming_channel: $s, played_game: $g);
select $s, $g;
distinct;
reduce $gameCount = count($g) groupby $s;
sort $gameCount desc;
limit 1;
fetch { "streamName": $s.name, "gameCount": $gameCount };

match
$s isa stream, has name $sn;
$rel isa vip_status (channel_with_vips: $s, vip_user: $u);
reduce $vip_count = count($rel) groupby $s, $sn;
sort $vip_count desc;
limit 3;
fetch {
  "stream_name": $sn,
  "vip_count": $vip_count
};

match
$s isa stream, has followers $f;
$g isa game, has name "Rust";
game_play (streaming_channel: $s, played_game: $g);
$f > 1000000;
fetch {
  "StreamName": $s.name,
  "StreamURL": $s.url,
  "Followers": $f
};

match
$s isa stream, has created_at $ca;
$l isa language, has name "en";
language_usage (channel: $s, used_language: $l);
$ca < 2012-01-01T00:00:00;
fetch {
  "stream": $s.name,
  "created_at": $ca
};

match
$s isa stream;
$u isa user;
moderation (moderating_user: $u, moderated_channel: $s);
vip_status (vip_user: $u, vip_channel: $s);
fetch {
  "streamName": $s.name,
  "userName": $u.name
};

match
$s isa stream, has created_at $ca;
sort $ca desc;
limit 3;
fetch {
  "name": $s.name,
  "created_at": $ca
};

match
$u isa user, has name $name;
$s isa stream;
moderation (moderating_user: $u, moderated_channel: $s);
reduce $count = count($s) groupby $u, $name;
sort $count desc;
limit 5;
fetch { "userName": $name, "streamCount": $count };

match
$u isa user, has name "itsbigchase";
$s isa stream;
