  "stream_url": $s.url
};

match
$s isa stream, has description $d;
$d like ".*hilarious moments.*";
$g isa game;
game_play (streaming_channel: $s, played_game: $g);
reduce $count = count($s) groupby $g;
sort $count desc;
limit 3;
fetch {
  "game": $g.name,
  "stream_count": $count
};

match
$s isa stream;
$l isa language;
language_usage (channel: $s, used_language: $l);
reduce $languageCount = count($l) groupby $s;
match
$languageCount > 2;
$s has name $streamName;
fetch {
  "streamName": $streamName,
  "languageCount": $languageCount
};

match
$s isa stream, has name $sn;
$u isa user;
$s2 isa stream;
chat_activity (channel_with_chatters: $s, chatting_user: $u);
chat_activity (chatting_user: $u, channel_with_chatters: $s2);
select $s, $sn, $u;
distinct;
reduce $chatter_count = count groupby $s, $sn;
sort $chatter_count desc;
limit 10;
fetch { "stream_name": $sn, "chatter_count": $chatter_count };

match
$s isa stream;
