$m isa movie;
acted_in (actor: $p, film: $m);
reviewed (reviewer: $p, film: $m);
fetch {
  "person_name": $p.name,
  "movie_title": $m.title
};

match
$p isa person;
$m isa movie;
$other isa person;
directed (director: $p, film: $m);
follows (follower: $p, followed: $other);
select $p;
distinct;
fetch {
  "name": $p.name
};

match
$r isa reviewed (reviewer: $p, film: $m);
$r has summary $s;
select $s;
distinct;
fetch { "review_summaries": $s };

match
$p isa person;
$m isa movie, has released $r;
$r < 1980;
$rel isa acted_in (actor: $p, film: $m);
reduce $count = count($rel) groupby $p;
sort $count desc;
limit 3;
fetch { "actor": $p.name, "roleCount": $count };

match
$p isa person;
$m isa movie;
directed (director: $p, film: $m);
produced (producer: $p, film: $m);
fetch {
  "MovieTitle": $m.title,
  "PersonName": $p.name
};

cypher:
MATCH (m:Movie)<-[:REVIEWED]-(p:Person)
WHERE EXISTS {
  MATCH (p)-[r:REVIEWED]->(m)
  WHERE r.summary = 'Fun, but a little far fetched'
}
RETURN m.title

typeql:
match
$m isa movie;
$r isa reviewed (reviewer: $p, film: $m);
$r has summary "Fun, but a little far fetched";
fetch {
  "title": $m.title
};

