match
$u isa user;
rated (user: $u, film: $m);
$m isa movie;
not {
  rated (user: $u, film: $m2);
  $m2 isa movie;
  in_genre (film: $m2, genre: $g);
  $g isa genre, has name "Sci-Fi";
};
select $u;
distinct;
fetch {
  "name": $u.name
};

