with fun org_count_in_country($country: country) -> integer:
  match
  $city isa city;
  $org isa organization;
  location-contains (parent: $country, child: $city);
  located_in (organization: $org, city: $city);
  return count;
match
$co isa country;
$c isa city, has city_name $cn;
location-contains (parent: $co, child: $c);
let $count = org_count_in_country($co);
$count > 100;
select $cn;
distinct;
limit 3;
fetch { "name": $cn };

match
$o isa organization;
board_member_of (organization: $o, member: $p);
reduce $count = count($p) groupby $o;
sort $count desc;
limit 3;
fetch { "organizationName": $o.name, "boardMemberCount": $count };

match
$a isa article, has title $title, has date $date, has author $author, has article_summary $summary;
$o isa organization, has name $n;
$n like ".*New Energy.*";
mentions (article: $a, mentioned: $o);
sort $date desc;
limit 3;
fetch {
  "title": $title,
  "date": $date,
  "author": $author,
