reduce $count = count($o) groupby $p, $n;
match $count > 1;
sort $count desc;
limit 3;
fetch { "personName": $n, "orgCount": $count };

match
\$o isa organization, has name \$n, has motto \$m;
\$m != "";
sort \$n;
limit 3;
fetch {
  "name": \$n
};

match
$o isa organization, has founding-date $fd;
$fd < 1975-01-01;
mentions (article: $a, mentioned: $o);
$a has title $t, has date $d, has sentiment $s;
sort $d desc;
limit 3;
fetch {
  "title": $t,
  "date": $d,
  "sentiment": $s
};

match
$o isa organization, has revenue $r;
$r > 100000000;
in_category (organization: $o, category: $ic);
$ic isa industry_category, has industry_category_name $name;
select $name;
distinct;
limit 3;
fetch { "name": $name };

match
$org isa organization;
$cat isa industry_category, has industry_category_name "Electronic Products Manufacturers";
in_category (organization: $org, category: $cat);
$city isa city;
located_in (organization: $org, city: $city);
$country isa country, has country_name $cn;
location-contains (parent: $country, child: $city);
reduce $count = count($org) groupby $country, $cn;
sort $count desc;
limit 3;
fetch { "country": $cn, "orgCount": $count };

match
$o isa organization, has name $name;
$c isa city, has population $pop;
$pop > 5000000;
located_in (organization: $o, city: $c);
limit 3;
fetch { "name": $name };

match
$a isa article;
$c isa chunk;
has_chunk (article: $a, chunk: $c);
$city isa city, has city_name $cn;
mentions (article: $a, mentioned: $city);
{
  $a has title $t; $t like ".*finance.*";
} or {
  $a has article_summary $s; $s like ".*finance.*";
} or {
  $c has text $txt; $txt like ".*finance.*";
};
reduce $count = count($a) groupby $city, $cn;
sort $count desc;
limit 3;
fetch { "city": $cn, "articleCount": $count };

match
$org isa organization, has name $org_name;
$ceo isa person, has name $person_name;
$board_member isa person, has name $person_name;
ceo_of (organization: $org, ceo: $ceo);
board_member_of (organization: $org, member: $board_member);
limit 3;
fetch {
  "organizationName": $org_name,
  "personName": $person_name
};

match
$org isa organization, has name $n;
$supplier isa organization;
$subsidiary isa organization;
supplies (supplier: $supplier, customer: $org);
subsidiary_of (parent: $org, subsidiary: $subsidiary);
$supplierCity isa city;
$supplierCountry isa country, has country_name "Europe";
$subsidiaryCity isa city;
$subsidiaryCountry isa country, has country_name "Europe";
located_in (organization: $supplier, city: $supplierCity);
location-contains (parent: $supplierCountry, child: $supplierCity);
located_in (organization: $subsidiary, city: $subsidiaryCity);
location-contains (parent: $subsidiaryCountry, child: $subsidiaryCity);
select $n;
distinct;
fetch { "name": $n };

match
$o isa organization;
supplies (customer: $o, supplier: $s);
reduce $supplierCount = count($s) groupby $o;
sort $supplierCount desc;
limit 3;
fetch {
  "organizationName": $o.name,
  "supplierCount": $supplierCount
};

match
$o isa organization;
$a isa article, has date $d;
mentions (article: $a, mentioned: $o);
$d >= 2021-01-01T00:00:00;
$d < 2022-01-01T00:00:00;
reduce $articleCount = count($a) groupby $o;
sort $articleCount desc;
limit 3;
fetch {
  "organizationName": $o.name,
  "articleCount": $articleCount
};

match
$org isa organization, has is_public true;
ceo_of (organization: $org, ceo: $ceo);
parent_of (parent: $ceo, child: $child);
$child has name $child_name;
$ceo has name $ceo_name;
limit 3;
fetch {
  "ChildName": $child_name,
  "CEOName": $ceo_name
};

match
$org isa organization, has name $org_name;
$sub isa organization;
$city isa city, has city_name $city_name;
subsidiary_of (parent: $org, subsidiary: $sub);
located_in (organization: $org, city: $city);
located_in (organization: $sub, city: $city);
limit 5;
fetch {
  "Organization": $org_name,
  "City": $city_name
};

match
$o isa organization, has is_dissolved true, has name $n;
$a isa article, has date $d;
mentions (article: $a, mentioned: $o);
sort $d desc;
limit 3;
fetch { "name": $n };

match
$a isa article;
$o isa organization;
$ic isa industry_category, has industry_category_name "Technology";
$c isa city;
$co isa country;
mentions (article: $a, mentioned: $o);
in_category (organization: $o, category: $ic);
located_in (organization: $o, city: $c);
location-contains (parent: $co, child: $c);
reduce $count = count($a) groupby $co;
sort $count desc;
limit 3;
fetch {
  "country": $co.country_name,
  "articleCount": $count
};

match
$o isa organization;
ceo_of (organization: $o, ceo: $p);
reduce $ceo_count = count($p) groupby $o;
match $ceo_count > 2;
limit 3;
fetch { "name": $o.name };

match
$a isa article;
$o isa organization, has name $n;
mentions (article: $a, mentioned: $o);
{ $a has article_summary $s; $s like ".*environmental.*"; } or { $a has title $t; $t like ".*environmental.*"; };
select $n;
distinct;
limit 3;
fetch { "name": $n };

match
$a isa article, has site_name "RCR Wireless News";
$o isa organization;
mentions (article: $a, mentioned: $o);
limit 5;
fetch {
  "name": $o.name
};

match
$o isa organization, has is_dissolved true, has name $org_name;
$p isa person, has name $ceo_name;
ceo_of (organization: $o, ceo: $p);
fetch {
  "CEO": $ceo_name,
  "Organization": $org_name
};

match
$o isa organization, has is_dissolved true;
$c isa city, has city_name $name;
located_in (organization: $o, city: $c);
reduce $count = count($o) groupby $c, $name;
sort $count desc;
limit 1;
fetch {
  "city": $name,
  "dissolved_organizations": $count
};

match
$p isa person, has name "Julie Spellman Sweet";
parent_of (parent: $p, child: $child);
$child isa person;
fetch {
  "childName": $child.name,
  "childId": $child.person_id,
  "childSummary": $child.summary
};

match
$country isa country, has country_name "United States of America";
$city isa city;
location-contains (parent: $country, child: $city);
$org isa organization;
located_in (organization: $org, city: $city);
fetch {
  "organizationName": $org.name
};

match
$o isa organization, has is_public true;
$c isa city;
located_in (organization: $o, city: $c);
reduce $count = count($o) groupby $c;
sort $count desc;
limit 1;
fetch {
  "city": $c.city_name,
  "publicOrganizations": $count
};

match
$a isa article;
$o isa organization, has name "SAP";
mentions (article: $a, mentioned: $o);
$a has sentiment $s;
sort $s desc;
limit 1;
fetch { "author": $a.author };

match
$o isa organization, has is_public true;
$a isa article, has date $d;
mentions (article: $a, mentioned: $o);
sort $d desc;
limit 3;
fetch {
  "title": $a.title,
  "summary": $a.article_summary,
  "date": $d
};

match
$c isa city, has city_name "Seattle";
$o isa organization;
$ic isa industry_category, has industry_category_name $icn;
located_in (organization: $o, city: $c);
in_category (organization: $o, category: $ic);
select $icn;
distinct;
fetch { "IndustryCategory": $icn };

match
$o isa organization, has revenue $r;
$r > 50000000;
$c isa city;
$country isa country, has country_name $name;
located_in (organization: $o, city: $c);
location-contains (parent: $country, child: $c);
select $name;
distinct;
fetch { "Country": $name };

match
$o isa organization, has motto $m;
$m like ".*technology.*";
fetch {
  "name": $o.name,
  "motto": $m
};

match
$parentOrg isa organization;
subsidiary_of (parent: $parentOrg, subsidiary: $subOrg);
reduce $numSubsidiaries = count($subOrg) groupby $parentOrg;
match $numSubsidiaries > 1;
fetch {
  "OrganizationName": $parentOrg.name,
  "numSubsidiaries": $numSubsidiaries
};

match
$a isa article, has date $d;
$d >= 2022-01-01T00:00:00;
$d < 2023-01-01T00:00:00;
$o isa organization, has name $n;
mentions (article: $a, mentioned: $o);
limit 3;
fetch { "organization_name": $n };

match
$o isa organization, has name "Accenture";
$a isa article, has title $t, has sentiment $s;
mentions (article: $a, mentioned: $o);
sort $s desc;
limit 1;
fetch {
  "title": $t,
  "sentiment": $s
};

match
$o isa organization, has nbr_employees $e;
$e > 50;
$e < 200;
located_in (organization: $o, city: $c);
$c has city_name $cn;
select $cn;
distinct;
fetch { "cityName": $cn };

match
$o1 isa organization, has name "SAP";
$o2 isa organization;
competes_with (competitor: $o1, competitor: $o2);
fetch {
  "competitorName": $o2.name
};

match
$p isa person;
$o isa organization;
invested_in (investor: $p, organization: $o);
board_member_of (member: $p, organization: $o);
limit 3;
fetch { "personName": $p.name };

match
$a isa article, has title "Funds for Consumer Behavior Specialist Infinite Analytics";
$o isa organization;
mentions (article: $a, mentioned: $o);
fetch {
  "name": $o.name
};

match
$c isa country, has country_name "United States of America";
location-contains (parent: $c, child: $ci);
$ci isa city;
located_in (organization: $o, city: $ci);
reduce $count = count($o);

match
$o isa organization;
$c isa city;
located_in (organization: $o, city: $c);
reduce $orgCount = count($o) groupby $c;
sort $orgCount desc;
limit 5;
fetch {
  "cityName": $c.city_name,
  "orgCount": $orgCount
};

match
$o isa organization, has nbr_employees $e;
sort $e desc;
limit 1;
fetch {
  "organization": $o.name,
  "numberOfEmployees": $e
};

match
$a isa article, has sentiment $s;
$o isa organization, has revenue $r;
$r > 1000000000.0;
mentions (article: $a, mentioned: $o);
sort $s desc;
limit 3;
fetch {
  "title": $a.title,
  "sentiment": $s,
  "date": $a.date
};

match
$a isa article, has date $d;
$o isa organization, has name "Accenture";
mentions (article: $a, mentioned: $o);
sort $d desc;
limit 5;
fetch {
  "title": $a.title,
  "date": $d,
  "author": $a.author,
  "siteName": $a.site_name,
  "summary": $a.article_summary
};

match
$o isa organization, has name "New Energy Group";
invested_in (organization: $o, investor: $investor);
$investor has name $investor_name;
try { $investor has person_id $pid; };
try { $investor has organization_id $oid; };
fetch {
  "InvestorName": $investor_name,
  "PersonID": $pid,
  "OrganizationID": $oid
};

match
$o isa organization, has is_dissolved true;
fetch {
  "organizationName": $o.name,
  "organizationSummary": $o.summary
};

match
$o isa organization;
$ic isa industry_category, has industry_category_name "Electronic Products Manufacturers";
in_category (organization: $o, category: $ic);
fetch {
  "organizationName": $o.name
};

match
$o isa organization, has nbr_employees $e;
$e > 500;
$c isa city, has city_name $name;
located_in (organization: $o, city: $c);
select $name;
distinct;
limit 3;
fetch { "name": $name };

match
$parent isa organization, has name "Accenture";
$subsidiary isa organization;
subsidiary_of (parent: $parent, subsidiary: $subsidiary);
fetch {
  "SubsidiaryName": $subsidiary.name
};

match
$accenture isa organization, has name "Accenture";
$supplier isa organization;
supplies (supplier: $supplier, customer: $accenture);
fetch {
  "name": $supplier.name
};

match
$p isa person, has name $name;
$rel isa parent_of ($p, $other);
$other isa person;
reduce $connections = count($rel) groupby $p, $name;
sort $connections desc;
limit 1;
fetch {
  "person": $name,
  "connections": $connections
};

match
$a isa article, has site_name "MrWeb", has date $d;
mentions (article: $a, mentioned: $o);
$o isa organization, has name $n;
sort $d;
limit 3;
fetch { "name": $n };

match
$o isa organization, has is_public true;
$p isa person, has name "Julie Spellman Sweet";
ceo_of (organization: $o, ceo: $p);
fetch {
  "name": $o.name
};

match
$o isa organization, has is_public true, has name $org_name;
$ceo isa person, has summary $s, has name $ceo_name;
ceo_of (organization: $o, ceo: $ceo);
{ $s like ".*female.*"; } or { $s like ".*Female.*"; } or { $s like ".*woman.*"; } or { $s like ".*Woman.*"; };
fetch {
  "OrganizationName": $org_name,
  "CEOName": $ceo_name
};

match
$o isa organization, has revenue $r, has name $org_name;
$r > 100000000;
$c isa city, has city_name $city_name;
$co isa country, has country_name $country_name;
$country_name != "United States of America";
located_in (organization: $o, city: $c);
location-contains (parent: $co, child: $c);
fetch {
  "OrganizationName": $org_name,
  "Revenue": $r,
  "CityName": $city_name,
  "CountryName": $country_name
};

match
$o isa organization;
$p isa person;
board_member_of (organization: $o, member: $p);
reduce $count = count($p) groupby $o;
sort $count desc;
limit 1;
fetch { "organizationName": $o.name };

match
$p isa person;
invested_in (investor: $p, organization: $o);
reduce $count = count($o) groupby $p;
sort $count desc;
limit 3;
fetch {
  "InvestorName": $p.name,
  "numInvestments": $count
};

match
$p isa person;
parent_of (parent: $p, child: $c);
reduce $childrenCount = count($c) groupby $p;
sort $childrenCount desc;
limit 1;
fetch {
  "personName": $p.name,
  "childrenCount": $childrenCount
};

match
$o isa organization, has nbr_employees $e;
$c isa city, has city_name "Seattle";
located_in (organization: $o, city: $c);
sort $e desc;
limit 1;
fetch {
  "name": $o.name
};

match
$o isa organization, has nbr_employees $n;
$c isa city, has city_name "Seattle";
located_in (organization: $o, city: $c);
$n > 500;
fetch {
  "name": $o.name,
  "nbr_employees": $n
};

match
$a isa article, has sentiment $s;
$s < 0.5;
mentions (article: $a, mentioned: $o);
$o isa organization;
limit 3;
fetch { "name": $o.name };

match
$o isa organization, has name $n;
competes_with (competitor: $o, competitor: $c);
reduce $count = count($c) groupby $o, $n;
sort $count desc;
limit 1;
fetch { "organizationName": $n, "competitorCount": $count };

match
$org isa organization, has name "New Energy Group";
supplies (customer: $org, supplier: $supplier);
$article isa article;
mentions (article: $article, mentioned: $supplier);
fetch {
  "title": $article.title,
  "date": $article.date,
  "author": $article.author,
  "summary": $article.article_summary
};

match
$o isa organization;
subsidiary_of (parent: $o, subsidiary: $s);
reduce $count = count($s) groupby $o;
sort $count desc;
limit 1;
fetch { "organizationName": $o.name, "numSubsidiaries": $count };

match
$ceo isa person, has name $ceo_name;
$child isa person, has name $child_name;
$org isa organization;
$otherOrg isa organization, has name $other_org_name;
ceo_of (ceo: $ceo, organization: $org);
parent_of (parent: $ceo, child: $child);
board_member_of (member: $child, organization: $otherOrg);
fetch {
  "CEO": $ceo_name,
  "Child": $child_name,
  "BoardMemberOf": $other_org_name
};

match
$a isa article, has sentiment $s, has date $d;
$s > 0.9;
$o isa organization, has name $n;
mentions (article: $a, mentioned: $o);
sort $d;
limit 3;
fetch { "name": $n };

match
$o isa organization, has revenue $rev;
$p isa person;
ceo_of (organization: $o, ceo: $p);
sort $rev desc;
limit 5;
fetch {
  "CEO": $p.name,
  "Organization": $o.name,
  "Revenue": $rev
};

match
$o isa organization;
board_member_of (organization: $o, member: $p);
reduce $count = count($p) groupby $o;
match $count >= 2;
fetch { "name": $o.name };

match
$org isa organization, has revenue $r;
$r < 10000000;
$city isa city;
$country isa country, has country_name $cn;
located_in (organization: $org, city: $city);
location-contains (parent: $country, child: $city);
select $cn;
distinct;
fetch { "country_name": $cn };

match
$o isa organization, has nbr_employees $n, has is_dissolved false;
$n < 50;
fetch {
  "name": $o.name
};

match
$o isa organization, has revenue $r;
$c isa city, has city_name $cn;
located_in (organization: $o, city: $c);
$r > 1000000;
fetch {
  "organizationName": $o.name,
  "cityName": $cn,
  "revenue": $r
};

match
$ceo isa person, has name "Julie Spellman Sweet";
ceo_of (ceo: $ceo, organization: $org);
$article isa article;
mentions (article: $article, mentioned: $org);
$article has date $d;
sort $d desc;
limit 5;
fetch {
  "title": $article.title,
  "date": $article.date,
  "author": $article.author,
  "siteName": $article.site_name,
  "summary": $article.article_summary
};

match
$o isa organization, has nbr_employees $emp, has name $org_name;
$emp > 10000;
$c isa city;
located_in (organization: $o, city: $c);
$co isa country, has country_name $co_name;
location-contains (parent: $co, child: $c);
not { $co_name == "United States of America"; };
fetch {
  "OrganizationName": $org_name,
  "NumberOfEmployees": $emp,
  "CountryName": $co_name
};

match
$o isa organization, has is_public false, has revenue $r, has name $n;
sort $r desc;
limit 1;
fetch {
  "name": $n,
  "revenue": $r
};

match
$o isa organization, has is_dissolved true;
invested_in (organization: $o, investor: $investor);
$investor has name $name;
select $investor, $name;
distinct;
fetch {
  "InvestorName": $name
};

match
$o isa organization;
$ic isa industry_category;
in_category (organization: $o, category: $ic);
reduce $orgCount = count($o) groupby $ic;
sort $orgCount desc;
limit 3;
fetch {
  "Industry": $ic.industry_category_name,
  "orgCount": $orgCount
};

match
$c isa city, has city_name "Rome";
located_in (organization: $o, city: $c);
$a isa article;
mentions (article: $a, mentioned: $o);
$a has date $d;
sort $d desc;
limit 3;
fetch {
  "title": $a.title,
  "date": $d,
  "author": $a.author,
  "summary": $a.article_summary
};

match
$o isa organization;
$c isa city;
$co isa country;
located_in (organization: $o, city: $c);
location-contains (parent: $co, child: $c);
$co has country_name $country;
reduce $orgCount = count($o) groupby $co, $country;
sort $orgCount desc;
limit 5;
fetch { "country": $country, "orgCount": $orgCount };

match
$c isa city, has city_name $cn;
$o isa organization;
$ic isa industry_category;
located_in (organization: $o, city: $c);
in_category (organization: $o, category: $ic);
select $c, $cn, $ic;
distinct;
reduce $count = count($ic) groupby $c, $cn;
match $count > 2;
fetch { "cityName": $cn };

match
$competitor isa organization;
competes_with (competitor: $competitor, competitor: $o);
$o isa organization;
reduce $mentionCount = count($o) groupby $competitor;
sort $mentionCount desc;
limit 3;
fetch {
  "organization": $competitor.name,
  "mentionCount": $mentionCount
};

match
$o isa organization, has nbr_employees $n, has summary $s, has name $name;
sort $n asc;
limit 1;
fetch {
  "name": $name,
  "summary": $s
};

match
$o isa organization, has name "New Energy Group";
board_member_of (organization: $o, member: $p);
$p isa person;
fetch {
  "boardMemberName": $p.name,
  "boardMemberId": $p.person_id,
  "boardMemberSummary": $p.summary
};

match
$ceo isa person, has name $ceo_name;
$org isa organization, has name $org_name;
ceo_of (ceo: $ceo, organization: $org);
$article isa article, has author $author, has title $article_title;
mentions (article: $article, mentioned: $org);
let $name_val = $ceo_name;
let $author_val = $author;
$name_val == $author_val;
limit 3;
fetch {
  "organization": $org_name,
  "ceo": $ceo_name,
  "article_title": $article_title
};

match
$a isa article;
mentions (article: $a, mentioned: $o);
$o isa organization;
{ $a has title $t; $t like ".*cybersecurity.*"; } or { $a has article_summary $s; $s like ".*cybersecurity.*"; };
$o has name $n;
select $n;
distinct;
limit 3;
fetch { "name": $n };

match
$org isa organization;
$cat isa industry_category, has industry_category_name "Software";
in_category (organization: $org, category: $cat);
$article isa article;
mentions (article: $article, mentioned: $org);
$city isa city;
located_in (organization: $org, city: $city);
select $city;
distinct;
fetch { "city_name": $city.city_name };

match
$a isa article;
$o isa organization;
mentions (article: $a, mentioned: $o);
{ $a has article_summary $s; $s like ".*security threat.*"; } or { $a has title $t; $t like ".*security threat.*"; };
select $o;
distinct;
fetch { "name": $o.name };

match
$p isa person;
$o isa organization, has revenue $r;
$r > 100000000;
invested_in (investor: $p, organization: $o);
fetch {
  "InvestorName": $p.name,
  "OrganizationName": $o.name
};

match
$parentOrg isa organization, has is_public true;
$subOrg isa organization, has is_public false;
subsidiary_of (parent: $parentOrg, subsidiary: $subOrg);
select $parentOrg;
