mentions (article: $a, mentioned: $o);
{ $a has title $t; $t like ".*financial crisis.*"; } or { $a has article_summary $s; $s like ".*financial crisis.*"; };
reduce $count = count($a) groupby $o;
sort $count desc;
limit 3;
fetch {
  "organizationName": $o.name,
  "mentionCount": $count
};

