with fun investment_count($i: person) -> integer:
  match
  $o isa organization;
  invested_in (organization: $o, investor: $i);
  located_in (organization: $o, city: $c);
  location-contains (parent: $country, child: $c);
  $country isa country, has country_name "Italy";
  return count;

