cypher:
MATCH (o:Organization)-[:IN_CITY]->(c:City)-[:IN_COUNTRY]->(co:Country)
WHERE o.nbrEmployees > 10000 AND NOT EXISTS {
    MATCH (capital:City)-[:IN_COUNTRY {capital: true}]->(co)
    WHERE c = capital
}
RETURN o.name AS OrganizationName, o.nbrEmployees AS NumberOfEmployees, c.name AS CityName, co.name AS CountryName

MATCH (org:Organization)-[:IN_CITY]->(city:City)-[:IN_COUNTRY]->(country:Country)
WHERE NOT EXISTS {
  MATCH (capital:City)-[:IN_COUNTRY {capital: true}]->(country)
  WHERE city = capital
}
RETURN org.name AS organizationName, city.name AS cityName, country.name AS countryName

typeql:
match
  $o isa organization;
  $p isa person;
  (organization: $o, ceo: $p) isa ceo_of;
  $a isa article;
  $p has name $p_name;
  $o has name $o_name;
sort $o_name asc;
limit 3;
fetch { "organization": $o.name, "article_title": $a.title };

match
  $a isa article;
  $o isa organization;
  $city isa city, has city_name $cn;
  (article: $a, mentioned: $o) isa mentions;
  (organization: $o, city: $city) isa located_in;
reduce $mentions = count($a) groupby $city, $cn;
sort $mentions desc;
limit 5;
fetch { "city": $cn, "mentions": $mentions };

match
  $o isa organization;
  $a isa article, has sentiment $s;
  $s < 0;
  mentions (article: $a, mentioned: $o);
reduce $avg = mean($s) groupby $o;
sort $avg asc;
limit 3;
fetch { "organization": $o.name, "avgSentiment": $avg };

match
  $o1 isa organization;
  $ceo1 isa person;
  $o2 isa organization;
  $ceo2 isa person;
  (organization: $o1, ceo: $ceo1) isa ceo_of;
  (organization: $o2, ceo: $ceo2) isa ceo_of;
fetch { "org1": $o1.name, "org2": $o2.name };

match
  $o isa organization;
  $c isa city;
  $country isa country;
  (organization: $o, city: $c) isa located_in;
(child: $c, parent: $country) isa location-contains; fetch { "organization": $o.name, "capital": $c.city_name };

match
  $o isa organization, has name $org_name;
  $ceo isa person, has name $ceo_name;
  $c isa industry_category, has industry_category_name "Healthcare";
  (organization: $o, ceo: $ceo) isa ceo_of;
  (organization: $o, category: $c) isa in_category;
  $ceo_name like ".*Mrs\\..*|.*Ms\\..*|.*Miss.*";
fetch { "organization": $org_name, "ceo": $ceo_name };

cypher:
MATCH (org:Organization)-[:IN_CITY]->(city:City)-[:IN_COUNTRY]->(country:Country)
WHERE NOT EXISTS {
    MATCH (capitalCity:City)-[:IN_COUNTRY {isCapital: true}]->(country)
    WHERE city = capitalCity
}
RETURN org.name AS organizationName, city.name AS cityName, country.name AS countryName

typeql:
match
  $o isa organization;
  $ceo isa person;
  $country isa country;
  $parent isa person;
  (organization: $o, ceo: $ceo) isa ceo_of;
  $city isa city; (organization: $o, city: $city) isa located_in;
(child: $city, parent: $country) isa location-contains; (parent: $ceo, child: $parent) isa parent_of; fetch { "organization": $o.name, "ceo": $ceo.name, "country": $country.country_name };

match
$rel isa ceo_of (organization: $o, ceo: $p);
$rel has start-date $sd;
$sd >= 2021-01-01T00:00:00;
fetch { "organization": $o.name, "ceo": $p.name };

with fun supply_chain($o: organization) -> { organization }:
  match
    {
      supplies (supplier: $s, customer: $o);
    } or {
      let $mid in supply_chain($o);
      supplies (supplier: $s, customer: $mid);
    };
  return { $s };
with fun supply_chain_size($o: organization) -> integer:
  match let $s in supply_chain($o);
  select $s;
  distinct;
  return count;
match
$o isa organization;
let $count = supply_chain_size($o);
sort $count desc;
limit 3;
fetch {
  "organization": $o.name,
  "supply_chain_size": $count
};

