  "y": $y
};

match
$u isa user, has color "#3CB371", has area $a;
$a < 3.0;
limit 5;
fetch {
  "handle": $u.handle,
  "key": $u.user_key,
  "y": $u.y_coordinate,
  "color": $u.color,
  "x": $u.x_coordinate,
  "area": $u.area,
  "size": $u.size
};

match
$u1 isa user;
$u2 isa user, has color "#FF4500";
interacted (source_user: $u1, target_user: $u2);
select $u1;
distinct;
limit 3;
fetch {
  "label": $u1.handle
};

match
$u isa user,
    has color "#FF4500",
    has size $s;
sort $s desc;
limit 5;
fetch {
    "handle": $u.handle,
    "user_key": $u.user_key,
    "y_coordinate": $u.y_coordinate,
    "x_coordinate": $u.x_coordinate,
    "area": $u.area,
    "size": $s
};

match
$u isa user, has size $s;
$other isa user;
interacted (source_user: $other, target_user: $u);
reduce $interactions = count($other) groupby $u, $s;
sort $interactions desc, $s desc;
limit 5;
fetch { "user": $u.handle, "size": $s, "interactions": $interactions };

match
$u1 isa user;
$u2 isa user, has x_coordinate $x;
$x > -500.0;
interacted (source_user: $u1, target_user: $u2);
select $u1;
distinct;
limit 3;
fetch {
  "handle": $u1.handle
};

match
$u1 isa user;
$u2 isa user, has y_coordinate $y;
$y < 0.0;
$r isa interacted (source_user: $u1, target_user: $u2);
reduce $count = count($r) groupby $u1;
sort $count desc;
limit 5;
fetch { "user": $u1.handle, "interactions": $count };

match
$u isa user, has x_coordinate $x;
$x < -5000.0;
sort $x;
limit 3;
fetch {
  "label": $u.handle,
  "x": $x
};

match
$u1 isa user, has size $s1;
$u2 isa user, has size $s2;
interacted (source_user: $u1, target_user: $u2);
$s1 > 2.0;
$s2 > 2.0;
sort $s1 desc;
limit 3;
fetch {
  "user": $u1.handle,
  "size": $s1
};

match
