match
$u1 isa user, has area $a, has handle $h;
$u2 isa user;
$rel isa interacted (source_user: $u1, target_user: $u2), has weight $w;
$w == 1.0;
sort $a desc;
limit 3;
fetch {
  "User": $h,
  "Area": $a
};

match
$u1 isa user;
$u2 isa user;
$r isa interacted (source_user: $u1, target_user: $u2);
$r has og_weight $ow, has weight $w;
$ow > $w;
fetch {
  "User1": $u1.handle,
  "User2": $u2.handle,
  "ogWeight": $ow,
  "weight": $w
};

match
$u1 isa user;
$u2 isa user;
$rel isa interacted (source_user: $u1, target_user: $u2);
$rel has weight $w;
$w == 1.0;
limit 3;
fetch {
  "label": $u2.handle
};

match
$u1 isa user;
$rel isa interacted (source_user: $u1, target_user: $u2);
$rel has size $s;
$s > 0.1;
reduce $count = count($rel) groupby $u1;
sort $count desc;
limit 5;
fetch {
  "userKey": $u1.user_key,
  "interactionCount": $count
};

match
$u1 isa user;
$rel isa interacted (source_user: $u1, target_user: $u2);
$rel has og_weight $w;
reduce $total = sum($w) groupby $u1;
sort $total desc;
limit 5;
fetch {
