};

match
$u isa user, has x_coordinate $x;
interacted (source_user: $u, target_user: $other);
$other isa user;
sort $x asc;
limit 3;
fetch {
  "user": $u
};

match
$u isa user, has y_coordinate $y;
interacted (source_user: $u, target_user: $other);
reduce $max_y = max($y) groupby $u;
sort $max_y desc;
limit 5;
fetch { "User": $u.handle, "Y_Coordinate": $max_y };

match
$u1 isa user, has handle $h1;
$u2 isa user, has handle $h2;
interacted (source_user: $u1, target_user: $u2);
{ $u1 has color "#FF4500"; } or { $u2 has color "#FF4500"; };
select $h1, $h2;
distinct;
fetch { "User1": $h1, "User2": $h2 };

match
$u isa user;
$rel isa interacted (source_user: $u, target_user: $u2);
reduce $interaction_count = count($u2) groupby $u;
match
$interaction_count > 2;
$rel2 isa interacted (source_user: $u);
$rel2 has weight $w;
reduce $weight_count = count($rel2) groupby $w;
sort $weight_count desc;
limit 10;
fetch {
  "weight": $w,
  "weightCount": $weight_count
};

match
$u isa user;
$r isa interacted (source_user: $u);
reduce $interactions = count($r) groupby $u;
sort $interactions desc;
limit 3;
