match
$u isa user;
not { $u has image $img; };
asked (asker: $u, asked_question: $q);
$q isa question, has created_at $ca;
sort $ca;
limit 3;
fetch {
  "title": $q.title,
  "link": $q.link,
  "created_at": $ca
};

match
$q isa question, has answered true, has favorites $f;
sort $f asc;
limit 5;
fetch {
  "title": $q.title,
  "favorites": $f,
  "link": $q.link
};

match
$q isa question;
$t isa tag, has tag_name "aws-lambda";
tagged (tagged_question: $q, tag: $t);
$u isa user, has reputation $rep;
$rep > 5000;
asked (asker: $u, asked_question: $q);
fetch {
  "question_title": $q.title,
  "question_link": $q.link,
  "user_name": $u.display_name,
  "user_reputation": $rep
};

match
  $u isa user, has reputation $rep, has display_name $dn;
  $rep > 10000;
  $q isa question, has created_at $ca;
  asked (asker: $u, asked_question: $q);
sort $ca desc;
limit 3;
fetch {
  "title": $q.title,
  "createdAt": $ca,
  "display_name": $dn
};

match
$u isa user, has user_link $ul;
$ul like ".*stackoverflow.*";
$q isa question, has favorites $f;
asked (asker: $u, asked_question: $q);
sort $f desc;
limit 5;
fetch {
  "title": $q.title,
  "favorites": $f,
  "link": $q.link
};

match
$u isa user;
$q isa question;
$t isa tag;
asked (asker: $u, asked_question: $q);
tagged (tagged_question: $q, tag: $t);
reduce $tag_count = count($t) groupby $u, $q;
match
$tag_count > 2;
$u has user_id $uid;
select $u, $uid;
distinct;
sort $uid asc;
limit 3;
fetch {
  "display_name": $u.display_name,
  "id": $u.user_id,
  "link": $u.user_link
};

match
$u isa user;
$q isa question, has answered false, has score $s;
$s < -1;
asked (asker: $u, asked_question: $q);
fetch {
  "display_name": $u.display_name,
  "user_id": $u.user_id,
  "user_link": $u.user_link
};

match
$q isa question, has created_at $ca, has down_votes $dv;
$ca < 2019-01-01T00:00:00;
sort $dv desc;
limit 5;
fetch {
  "title": $q.title,
  "down_votes": $dv
};

match
$q isa question, has favorites $f;
$t isa tag, has tag_name "graphql";
tagged (tagged_question: $q, tag: $t);
$f > 1;
$q has created_at $ca;
sort $ca asc;
limit 3;
fetch {
  "question": $q.title,
  "favorites": $f,
  "created_at": $ca
};

match
$q isa question, has down_votes $dv;
sort $dv desc;
limit 5;
fetch {
  "title": $q.title,
  "downVotes": $dv
};

match
  $q isa question, has score $s, has title $t;
  $s <= 0;
  $u isa user, has image $img, has display_name $dn;
  asked (asker: $u, asked_question: $q);
  $q has created_at $ca;
sort $ca asc;
limit 3;
fetch {
  "question_title": $t,
  "question_score": $s,
  "user_name": $dn,
  "user_image": $img
};

match
  $q isa question, has down_votes $dv, has title $t, has link $l;
  $dv > 5;
  $tag isa tag, has tag_name "aws-lambda";
  tagged (tagged_question: $q, tag: $tag);
fetch {
  "title": $t,
  "link": $l,
  "down_votes": $dv
};

match
$u isa user;
$q isa question;
asked (asker: $u, asked_question: $q);
reduce $count = count($q) groupby $u;
sort $count desc;
limit 5;
fetch {
  "user": $u.display_name,
  "question_count": $count
};

