$q isa question, has favorites 0;
asked (asker: $u, asked_question: $q);
fetch {
  "user_id": $u.user_id
};

match
$q isa question, has score $s;
$t isa tag, has tag_name "graphql";
tagged (tagged_question: $q, tag: $t);
$s > 0;
fetch {
  "title": $q.title,
  "text": $q.text,
  "link": $q.link,
  "score": $s
};

match
$q isa question, has down_votes $dv, has created_at $ca;
$t isa tag, has tag_name "apollo";
tagged (tagged_question: $q, tag: $t);
$dv > 0;
sort $ca asc;
limit 5;
fetch {
  "title": $q.title,
  "question_id": $q.question_id,
  "down_votes": $dv,
  "created_at": $ca
};

match
