with fun answered_count($u: user) -> integer:
  match
  asked (asker: $u, asked_question: $q);
  $q isa question, has answered true;
  return count;
with fun total_count($u: user) -> integer:
  match
  asked (asker: $u, asked_question: $q);
  $q isa question;
  return count;
match
$u isa user;
let $answered = answered_count($u);
let $total = total_count($u);
$total > 0;
let $answer_rate = $answered / $total;
sort $answer_rate desc;
limit 3;
fetch {
  "user": $u.display_name,
  "answerRate": $answer_rate
};

