match
$e isa fincen_entity, has name $name;
$f isa filing, has amount $a;
$a > 1000000;
filed (filer: $e, filing: $f);
reduce $count = count($f) groupby $e, $name;
sort $count desc;
limit 3;
fetch {
  "entity_name": $name,
  "transaction_count": $count
};

match
