filed (filer: $e, filing: $f);
fetch {
  "entity_name": $e.name,
  "entity_id": $e.entity_id
};

match
$f isa filing, has amount $a;
$a > 1000000;
$e isa fincen_entity, has name $name, has entity_id $eid;
benefits (filing: $f, beneficiary: $e);
fetch {
  "beneficiary_entity": $name,
  "beneficiary_entity_id": $eid
};

match
