$c isa category, has name $cn;
in_category (business: $b, category: $c);
not {
  reviews (review: $r, reviewed_business: $b);
  $r has text $t;
  $t like ".*awesome.*";
};
fetch {
  "CategoryWithoutAwesomeReviews": $cn
};

