with fun category_count($u: user) -> integer:
  match
    wrote (author: $u, review: $r);
    reviews (review: $r, reviewed_business: $b);
    in_category (business: $b, category: $c);
  select $c;
  distinct;
  return count;
match
$u isa user;
let $count = category_count($u);
reduce $max_count = max($count);
match
$u isa user;
let $count = category_count($u);
$count == $max_count;
wrote (author: $u, review: $r);
reviews (review: $r, reviewed_business: $b);
in_category (business: $b, category: $c);
fetch {
  "user": $u.name,
  "category": $c.name,
  "categoryCount": $count
};

with fun avg_stars($b: business) -> double:
  match
    reviews (review: $r, reviewed_business: $b);
    $r has stars $s;
  return mean($s);
match
$b isa business, has city "San Mateo";
let $avg = avg_stars($b);
reduce $max_avg = max($avg);
match
$b isa business, has city "San Mateo";
let $avg = avg_stars($b);
$avg == $max_avg;
reviews (review: $r, reviewed_business: $b);
fetch {
  "businessName": $b.name,
  "avgRating": $avg,
  "reviewText": $r.text,
  "reviewStars": $r.stars,
  "reviewDate": $r.date
};

with fun reviewed_by($b: business, $u: user) -> integer:
  match
    wrote (author: $u, review: $r);
    reviews (review: $r, reviewed_business: $b);
  return count;
match
$b isa business, has city "Missoula";
$u1 isa user, has user_id "u1";
$u2 isa user, has user_id "u2";
$u3 isa user, has user_id "u3";
$u4 isa user, has user_id "u4";
let $c1 = reviewed_by($b, $u1); $c1 > 0;
let $c2 = reviewed_by($b, $u2); $c2 > 0;
let $c3 = reviewed_by($b, $u3); $c3 > 0;
let $c4 = reviewed_by($b, $u4); $c4 > 0;
reviews (review: $r, reviewed_business: $b);
fetch {
  "business_name": $b.name,
  "review_text": $r.text
};

match
$b isa business, has city "San Mateo", has name $bn;
in_category (business: $b, category: $c);
sort $bn asc;
limit 3;
fetch {
  "businessName": $bn,
  "category": $c.name
};

with fun latest_review_date($u: user) -> datetime:
  match
    wrote (author: $u, review: $r);
    $r has date $d;
  return max($d);
match
$u isa user;
let $latest = latest_review_date($u);
sort $latest desc;
limit 3;
match
wrote (author: $u, review: $r);
reviews (review: $r, reviewed_business: $b);
reduce $review_count = count($r) groupby $b;
sort $review_count desc;
limit 3;
fetch {
  "businessName": $b.name,
  "reviewCount": $review_count
};

with fun distinct_date_count($b: business) -> integer:
  match
    reviews (review: $r, reviewed_business: $b);
    $r has date $d;
  select $d;
  distinct;
  return count;
with fun earliest_review_date($b: business) -> datetime:
  match
    reviews (review: $r, reviewed_business: $b);
    $r has date $d;
  return min($d);
match
$b isa business;
let $dc = distinct_date_count($b);
$dc >= 3;
let $earliest = earliest_review_date($b);
sort $earliest asc;
limit 3;
match
reviews (review: $r, reviewed_business: $b);
$r has date $d;
sort $d asc;
fetch {
  "businessName": $b.name,
  "reviewDate": $d
};

match
$b isa business, has name "Ducky's Car Wash";
in_category (business: $b, category: $c);
try {
  reviews (review: $r, reviewed_business: $b);
};
fetch {
