with fun all_previous($v: version) -> { version }:
  match
    {
      previous (newer_version: $v, older_version: $prev);
    } or {
      let $mid in all_previous($v);
      previous (newer_version: $mid, older_version: $prev);
    };
  return { $prev };
match
$m isa machine, has name "DC1-RCK-1-1-M-1";
runs (host_machine: $m, running_process: $proc);
instance_of (running_instance: $proc, template: $sw);
$sw isa software;
has_version (versioned_software: $sw, release_version: $cv);
let $pv in all_previous($cv);
select $pv;
distinct;
fetch {
  "PreviousVersions": $pv.name
};

with fun all_previous($v: version) -> { version }:
  match
    {
      previous (newer_version: $v, older_version: $prev);
    } or {
      let $mid in all_previous($v);
      previous (newer_version: $mid, older_version: $prev);
    };
  return { $prev };
match
$v isa version, has name "7.1";
let $prev in all_previous($v);
fetch {
  "previous_versions": $prev.name
};

