with fun all_reachable($sw: software) -> { software }:
  match
    {
      $dep is $sw;
    } or {
      depends_on (dependent: $sw, dependency: $dep);
      $dep isa software;
    } or {
      let $mid in all_reachable($sw);
      depends_on (dependent: $mid, dependency: $dep);
      $dep isa software;
    };
  return { $dep };
match
$app isa application, has name "crm";
depends_on (dependent: $app, dependency: $sw);
$sw isa software;
let $dep in all_reachable($sw);
select $dep;
distinct;
fetch {
  "DependencyName": $dep.name
};

with fun all_previous($v: version) -> { version }:
  match
    {
      previous (newer_version: $v, older_version: $prev);
    } or {
      let $mid in all_previous($v);
      previous (newer_version: $mid, older_version: $prev);
    };
  return { $prev };
match
$v isa version, has name "7.1";
let $prev in all_previous($v);
try {
  has_version (versioned_software: $sw, release_version: $prev);
  $sw has name $sw_name;
};
limit 3;
fetch {
  "PreviousVersion": $prev.name,
  "SoftwareDependency": $sw_name
};

with fun all_previous($v: version) -> { version }:
  match
    {
      previous (newer_version: $v, older_version: $prev);
    } or {
      let $mid in all_previous($v);
      previous (newer_version: $mid, older_version: $prev);
    };
  return { $prev };
match
$v isa version, has name "7.1";
let $prev in all_previous($v);
has_version (versioned_software: $sw, release_version: $prev);
$sw isa software;
