$o has ship_name $sn;
$o has ship_city $sc;
$o has ship_postal_code $spc;
$o has ship_country $sco;
$o has ship_address $sa;
$o has ship_region $sr;
$o has shipped_date $sd;
sort $sd;
limit 5;
fetch {
  "orderID": $oid,
  "shipName": $sn,
  "shipCity": $sc,
  "shipPostalCode": $spc,
  "shipCountry": $sco,
  "shipAddress": $sa,
  "shipRegion": $sr,
  "shippedDate": $sd
};

match
$c isa customer;
purchased (customer: $c, order: $o);
$r isa orders (order: $o, product: $p);
$r has discount 0.0;
reduce $order_count = count($o) groupby $c;
sort $order_count desc;
limit 5;
fetch {
  "customerID": $c.customer_id,
  "companyName": $c.company_name,
  "orderCount": $order_count
};

