$p isa product, has discontinued true;
supplies (supplier: $s, product: $p);
reduce $count = count($p) groupby $s;
sort $count desc;
limit 3;
fetch {
  "Supplier": $s.company_name,
  "discontinuedProducts": $count
};

match
$c isa customer;
purchased (customer: $c, order: $o);
reduce $order_count = count($o) groupby $c;
sort $order_count desc;
limit 3;
fetch {
  "customerID": $c.customer_id,
  "companyName": $c.company_name,
  "orderCount": $order_count
};

match
$p isa product, has reorder_level $rl;
$rl > 20;
sort $rl desc;
limit 5;
fetch {
  "productName": $p.product_name,
  "reorderLevel": $rl
};

match
$o isa order, has shipped_date $sd;
sort $sd desc;
limit 5;
fetch {
  "orderID": $o.order_id,
  "shippedDate": $sd
};

match
$c isa customer;
purchased (customer: $c, order: $o);
$rel isa orders (order: $o, product: $p);
$rel has quantity $q;
reduce $total = sum($q) groupby $c;
sort $total desc;
limit 3;
fetch { "customer": $c.company_name, "totalUnitsOrdered": $total };

match
$p isa product;
$c isa category, has category_name "Confections";
part_of (product: $p, category: $c);
$p has units_in_stock $stock;
sort $stock desc;
limit 3;
fetch {
  "productName": $p.product_name,
  "unitsInStock": $stock
};

match
$p isa product, has discontinued false, has units_on_order $units;
sort $units desc;
limit 5;
fetch {
  "productName": $p.product_name,
  "unitsOnOrder": $units
};

match
$c isa customer;
$o isa order, has ship_country "France";
purchased (customer: $c, order: $o);
limit 3;
fetch {
  "customerID": $c.customer_id,
  "companyName": $c.company_name,
  "contactName": $c.contact_name
};

match
orders (order: $o, product: $p1);
orders (order: $o, product: $p2);
$p1 has product_id $id1;
$p2 has product_id $id2;
$id1 < $id2;
reduce $freq = count($o) groupby $p1, $p2;
sort $freq desc;
limit 3;
fetch {
  "product1": $p1.product_name,
  "product2": $p2.product_name,
  "frequency": $freq
};

with fun max_order_price($p: product) -> double:
  match
    $rel isa orders (product: $p);
    $rel has order_unit_price $up;
  return max($up);
with fun min_order_price($p: product) -> double:
  match
    $rel isa orders (product: $p);
    $rel has order_unit_price $up;
  return min($up);
match
$p isa product;
let $max = max_order_price($p);
let $min = min_order_price($p);
let $variation = $max - $min;
sort $variation desc;
limit 3;
fetch {
  "productName": $p.product_name,
  "priceVariation": $variation
};

match
$c isa customer, has company_name "Rattlesnake Canyon Grocery";
purchased (customer: $c, order: $o);
$o has employee_id $eid;
select $eid;
distinct;
fetch {
  "employeeId": $eid
};

match
$o isa order, has ship_name $sn, has freight $f;
$f > 100.0;
sort $f desc;
limit 3;
fetch {
  "shipName": $sn,
  "freight": $f
};

with fun avg_freight($s: supplier) -> double:
  match
    supplies (supplier: $s, product: $p);
    orders (order: $o, product: $p);
    $o has freight $f;
  return mean($f);
match
$s isa supplier;
let $avg = avg_freight($s);
sort $avg desc;
limit 3;
fetch {
  "supplierName": $s.company_name,
  "avgFreight": $avg
};

with fun total_freight($c: customer) -> double:
  match
    purchased (customer: $c, order: $o);
    $o has freight $f;
  return sum($f);
match
$c isa customer;
let $total = total_freight($c);
$total > 1000.0;
fetch {
  "companyName": $c.company_name,
  "contactName": $c.contact_name,
  "contactTitle": $c.contact_title,
  "phone": $c.phone,
  "address": $c.address,
  "city": $c.city,
  "country": $c.country,
  "totalFreight": $total
};

