reduce $entityCount = count($e) groupby $a;
match $entityCount > 1;
$a has address $addr;
fetch { "Address": $addr, "entityCount": $entityCount };

match
$e isa offshore_entity;
$o isa officer;
same_name_as (named_source: $e, named_target: $o);
