with fun entity_count($i: intermediary) -> integer:
  match
    intermediary_of (intermediary: $i, offshore_entity: $e);
  select $e;
  distinct;
  return count;
match
$i isa intermediary;
let $count = entity_count($i);
$count > 1;
intermediary_of (intermediary: $i, offshore_entity: $e);
fetch {
  "officerName": $i.name,
  "entityName": $e.name
};

with fun address_count($e: offshore_entity) -> integer:
  match
    registered_address (registrant: $e, registered_addr: $a);
  select $a;
  distinct;
  return count;
match
$e isa offshore_entity;
let $count = address_count($e);
$count > 1;
registered_address (registrant: $e, registered_addr: $a);
fetch {
  "entityName": $e.name,
  "address": $a.address
};

with fun former_name_count($e: offshore_entity) -> integer:
  match
    $e has former_name $fn;
  select $fn;
  distinct;
  return count;
match
$e isa offshore_entity;
let $count = former_name_count($e);
$count > 1;
$e has former_name $fn;
fetch {
  "currentName": $e.name,
  "formerName": $fn
};

